package net.civeira.phylax.features.notification.message.application.policy;

import jakarta.enterprise.event.Observes;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.features.access.tenant.domain.TenantReference;
import net.civeira.phylax.features.notification.message.application.visibility.MessageEntityEnrichment;

public class InheritTenantExcludingRoot {

  /**
   * Constant for platformAdmin field
   *
   * @autogenerated FormulaPolicyGenerator
   */
  private static final String ROL_PLATFORM_ADMIN = "platform:admin";

  /**
   * @autogenerated FormulaPolicyGenerator
   * @param builder
   */
  public void calculate(@Observes MessageEntityEnrichment builder) {
    Actor actor = builder.getActor();
    if (!actor.hasRole(ROL_PLATFORM_ADMIN)) {
      builder.peek(dto -> dto.tenant(TenantReference.of(actor.getTenant().orElse(null))));
    }
  }
}
